  };
  let out = "Total: " + total + " " + un + "\n\n";
  if (hus.length && loose.length) {
    out += "LOOSE STOCK:\n";
    loose.forEach((e, i) => { out += line(e, i) + "\n"; });
    out += "\nHANDLING UNIT:\n";
    hus.forEach((e, i) => { out += line(e, i) + "\n"; });
  } else if (hus.length) {
    out += "HANDLING UNIT:\n";
    hus.forEach((e, i) => { out += line(e, i) + "\n"; });
